/* Title-based fallback lookup — returns NULL if no match */
typedef struct { const char *keyword; const unsigned short *data; } FallbackEntry;

static const FallbackEntry g_fallback_icons[] = {
    { "desktop", icon_desktop },
    { "desktop", icon_desktop_alt },
    { "retrobat", icon_retrobat },
    { "virtual", icon_virtual_desktop },
    { "steam", icon_steam },
    { "input", icon_input_only },
    { "terminate", icon_terminate },
    { "template", icon_template },
    { "custom", icon_custom_cover },
    { "box", icon_box },
    { NULL, NULL }
};

static const unsigned short *fallback_icon_for_title(const char *title)
{
    if (!title) return NULL;
    int i;
    for (i = 0; g_fallback_icons[i].keyword != NULL; i++) {
        /* Case-insensitive substring search */
        const char *h = title;
        const char *n = g_fallback_icons[i].keyword;
        int nlen = 0; while(n[nlen]) nlen++;
        while (*h) {
            int j = 0, match = 1;
            while (j < nlen && h[j]) {
                char a = h[j], b = n[j];
                if (a >= 'A' && a <= 'Z') a += 32;
                if (b >= 'A' && b <= 'Z') b += 32;
                if (a != b) { match = 0; break; }
                j++;
            }
            if (match && j == nlen) return g_fallback_icons[i].data;
            h++;
        }
    }
    return NULL;
}

